class MainActivity:ComponentActivity(),NfcAdapter.ReaderCallback {
    private val model:MainViewModel by viewModels()
    private val adapter by lazy { NfcAdapter.getDefaultAdapter(this) }
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContent{SpoolioTheme{SpoolioApp(model,adapter!=null)}}}
    override fun onResume(){super.onResume();adapter?.enableReaderMode(this,this,NfcAdapter.FLAG_READER_NFC_A,null)}
    override fun onPause(){adapter?.disableReaderMode(this);super.onPause()}
    override fun onTagDiscovered(tag:Tag)=model.nfc.onTag(tag)
}

@Composable private fun SpoolioTheme(content: @Composable () -> Unit){
    val colors=lightColorScheme(primary=Color(0xFF286354),secondary=Color(0xFF7A5731),background=Color(0xFFF8F6F0),surface=Color(0xFFFFFCF5),error=Color(0xFF9B2C2C))
    MaterialTheme(colorScheme=colors,typography=Typography(),content=content)
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun SpoolioApp(model:MainViewModel,nfcAvailable:Boolean){
    var custom by remember{mutableStateOf<CustomSeed?>(null)}
    var showCustom by remember{mutableStateOf(false)}
    Scaffold(topBar={TopAppBar(title={Column{Text("Spoolio",fontWeight=FontWeight.Bold);Text("Offline filament tag manager",style=MaterialTheme.typography.labelMedium)}})},floatingActionButton={ExtendedFloatingActionButton(onClick={custom=CustomSeed();showCustom=true}) { Text("Custom filament") }}){padding->
        Column(Modifier.padding(padding).padding(horizontal=16.dp).fillMaxSize()){
            if(!nfcAvailable)Notice("NFC is unavailable on this device. Offline catalog remains usable.",true)
            model.error?.let{Notice(it,true)}
            OutlinedTextField(model.query,{model.query=it},Modifier.fillMaxWidth().padding(top=12.dp),label={Text("Search brand, material, product, or color")},singleLine=true,trailingIcon={TextButton(onClick=model::search){Text("Search")}})
            when { model.loading -> Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator()}; model.selected!=null -> Detail(model,model.selected!!){model.selected=null}; else -> {ReadResult(model.nfc.lastRead){model.decodedSeed()?.let{custom=it;showCustom=true}};CatalogList(model.results,model::select)} }
        }
    }
    if(showCustom)CustomDialog(custom?:CustomSeed(),onDismiss={showCustom=false},onSave={b,m,p,c,h,d,w->model.saveCustom(b,m,p,c,h,d,w);showCustom=false})
}

@Composable private fun ReadResult(result:DecodeResult?,edit:()->Unit){when(result){is DecodeResult.Supported->Card(Modifier.fillMaxWidth().padding(top=8.dp)){Column(Modifier.padding(12.dp)){Text("Supported OpenSpool tag read",fontWeight=FontWeight.Bold);Text("Fields were decoded without rewriting the tag.");TextButton(onClick=edit){Text("Edit as a local record")}}};is DecodeResult.ReadOnly->Notice("Read-only tag: ${result.reason}",false);is DecodeResult.Rejected->Notice("Tag not editable: ${result.reason}",false);null->Unit}}

@Composable private fun CatalogList(entries:List<CatalogEntry>,select:(CatalogEntry)->Unit){
    Text("${entries.size} matches shown",Modifier.padding(vertical=12.dp),style=MaterialTheme.typography.labelLarge)
    LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp),contentPadding=PaddingValues(bottom=88.dp)){
        items(entries,key={it.packageId}){e->Card(Modifier.fillMaxWidth().clickable{select(e)}){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){
            val color=runCatching{Color(android.graphics.Color.parseColor(e.colorHex))}.getOrElse{Color.Gray}
            Box(Modifier.size(42.dp).background(color,RoundedCornerShape(12.dp)).semantics{contentDescription="${e.colorName} color sample"})
            Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text("${e.brand} · ${e.product}",fontWeight=FontWeight.SemiBold);Text("${e.material} — ${e.colorName}");Text("${e.diameterMm} mm · ${e.massG} g",style=MaterialTheme.typography.bodySmall)}}}
        }
    }
}

@Composable private fun Detail(model:MainViewModel,e:CatalogEntry,back:()->Unit){
    val intent=remember(e,model.profile){runCatching{model.intent(e)}.getOrNull()}
    Column(Modifier.verticalScrollCompat().padding(vertical=12.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
        TextButton(onClick=back){Text("‹ Back to catalog")}; Text("${e.brand} ${e.product}",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold); Text("${e.colorName} · ${e.material}")
        Info("Exact package","${e.diameterMm} mm · ${e.massG} g");Info("Nozzle",range(e.nozzleMinC,e.nozzleMaxC));Info("Bed",range(e.bedMinC,e.bedMaxC));Info("Barcode",e.gtin?:"Missing in source");Info("Provenance",if(e.sourceRevision=="user")"Local custom · every field user-provided" else "OFD ${e.sourceRevision} · catalog")
        Text("Tag compatibility",fontWeight=FontWeight.Bold);SingleChoiceSegmentedButtonRow{OpenSpoolProfile.entries.forEachIndexed{i,p->SegmentedButton(selected=model.profile==p,onClick={model.profile=p},shape=SegmentedButtonDefaults.itemShape(i,2)){Text(if(p==OpenSpoolProfile.CANONICAL)"Canonical" else "PAXX extensions")}}}
        intent?.let{Notice("NDEF payload ${it.payload.size} bytes before record overhead. Omitted locally retained fields: ${it.omittedFields.sorted().joinToString()}.",false)}
        Button(onClick={model.arm(e)},modifier=Modifier.fillMaxWidth()){Text("Prepare verified NFC write")}
        NfcPanel(model.nfc)
        Spacer(Modifier.height(90.dp))
    }
}

@Composable private fun NfcPanel(nfc:NfcCoordinator){ val s=nfc.state; if(s.phase!=WritePhase.DRAFT){Card(colors=CardDefaults.cardColors(containerColor=if(s.phase==WritePhase.VERIFIED)Color(0xFFDDEFE6) else Color(0xFFFFF1D8))){Column(Modifier.padding(14.dp)){Text(s.phase.name.replace('_',' '),fontWeight=FontWeight.Bold);Text(s.detail);if(s.phase==WritePhase.NEEDS_OVERWRITE_CONSENT)Button(onClick=nfc::approveOverwrite){Text("Approve overwrite for this intent")};if(s.phase!=WritePhase.VERIFIED)TextButton(onClick=nfc::cancel){Text("Cancel")}}}} }
@Composable private fun Info(label:String,value:String){Row(Modifier.fillMaxWidth()){Text(label,Modifier.width(120.dp),fontWeight=FontWeight.SemiBold);Text(value)}}
@Composable private fun Notice(text:String,error:Boolean){Surface(color=if(error)MaterialTheme.colorScheme.errorContainer else MaterialTheme.colorScheme.secondaryContainer,shape=RoundedCornerShape(10.dp)){Text(text,Modifier.padding(12.dp))}}
private fun range(a:Int?,b:Int?)=when{a==null&&b==null->"Missing in source";a==b->"$a °C";else->"${a?:"?"}–${b?:"?"} °C"}

@Composable private fun CustomDialog(seed:CustomSeed,onDismiss:()->Unit,onSave:(String,String,String,String,String,String,String)->Unit){var brand by remember(seed){mutableStateOf(seed.brand)};var material by remember(seed){mutableStateOf(seed.material)};var product by remember(seed){mutableStateOf(seed.product)};var color by remember(seed){mutableStateOf(seed.color)};var hex by remember(seed){mutableStateOf(seed.hex.ifBlank{"#000000"})};var diameter by remember(seed){mutableStateOf(seed.diameter)};var mass by remember(seed){mutableStateOf(seed.mass)};AlertDialog(onDismissRequest=onDismiss,title={Text(if(seed.brand.isBlank())"Custom filament" else "Edit decoded tag locally")},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(4.dp)){Text("Every saved field is marked as user-provided; missing tag fields stay blank until you enter them.",style=MaterialTheme.typography.bodySmall);listOf("Brand" to brand,"Material" to material,"Product" to product,"Color name" to color,"Color hex" to hex,"Diameter mm" to diameter,"Mass g" to mass).forEach{(label,value)->OutlinedTextField(value,{when(label){"Brand"->brand=it;"Material"->material=it;"Product"->product=it;"Color name"->color=it;"Color hex"->hex=it;"Diameter mm"->diameter=it;else->mass=it}},label={Text(label)},singleLine=true)}}},confirmButton={Button(onClick={onSave(brand,material,product,color,hex,diameter,mass)}){Text("Save locally")}},dismissButton={TextButton(onClick=onDismiss){Text("Cancel")}})}

