class MainViewModel(app:Application):AndroidViewModel(app){
    private val store=(app as SpoolioApplication).data
    val nfc=NfcCoordinator(app)
    var loading by mutableStateOf(true); private set
    var query by mutableStateOf("")
    var results by mutableStateOf<List<CatalogEntry>>(emptyList()); private set
    var selected by mutableStateOf<CatalogEntry?>(null)
    var error by mutableStateOf<String?>(null); private set
    var profile by mutableStateOf(OpenSpoolProfile.CANONICAL)
    private var customEntries:List<CatalogEntry> = emptyList()
    init { viewModelScope.launch { runCatching{withContext(Dispatchers.IO){store.ensureCatalog();val customs=store.user.user().customs().first().map(CustomRecord::asCatalogEntry);customs to store.catalog.catalog().browse()}}.onSuccess{(customs,catalog)->customEntries=customs;results=customs+catalog}.onFailure{error=it.message};loading=false } }
    fun search(){ val q=query.trim();if(q.length>120){error="Search is limited to 120 characters";return};viewModelScope.launch { runCatching{withContext(Dispatchers.IO){val catalog=if(q.isBlank())store.catalog.catalog().browse() else store.catalog.catalog().search(q.split(Regex("\\s+")).take(8).joinToString(" "){"\"${it.replace("\"","\"\"")}\"*"});val local=if(q.isBlank())customEntries else customEntries.filter{e->listOf(e.brand,e.material,e.product,e.colorName).any{it.contains(q,true)}};local+catalog}}.onSuccess{results=it;error=null}.onFailure{error="Search could not be completed"} } }
    fun select(entry:CatalogEntry){selected=entry;viewModelScope.launch(Dispatchers.IO){store.user.user().recent(Recent(entry.packageId,if(entry.sourceRevision=="user")"custom" else "catalog",encodeJsonObject(mapOf("package_id" to entry.packageId,"source_revision" to entry.sourceRevision)).decodeToString(),System.currentTimeMillis()))}}
    fun intent(entry:CatalogEntry):OpenSpoolIntent=OpenSpoolCodec.encode(entry.toRecord(),profile)
    fun arm(entry:CatalogEntry){runCatching{nfc.arm(intent(entry))}.onFailure{error=it.message}}
    fun saveCustom(brand:String,material:String,product:String,color:String,hex:String,diameter:String,mass:String){
        val record=FilamentRecord(UUID.randomUUID().toString(),null,null,FieldValue(brand,"user"),FieldValue(material,"user"),FieldValue(product,"user"),FieldValue(color,"user"),FieldValue(hex,"user"),FieldValue(diameter,"user"),FieldValue(mass.toIntOrNull()?:0,"user"),null,null,null,null,sourceRevision="user",provenance=Provenance.CUSTOM)
        runCatching{validateRecord(record)}.onFailure{error=it.message;return}; viewModelScope.launch {val saved=CustomRecord(record.packageId,brand,material,product,color,normalizeHex(hex),diameter,mass.toInt(),System.currentTimeMillis());withContext(Dispatchers.IO){store.user.user().save(saved)};val entry=saved.asCatalogEntry();customEntries=listOf(entry)+customEntries.filterNot{it.packageId==entry.packageId};results=listOf(entry)+results.filterNot{it.packageId==entry.packageId};selected=entry;error=null}
    }

    fun decodedSeed(): CustomSeed? {
        val values = (nfc.lastRead as? DecodeResult.Supported)?.values ?: return null
        fun text(k: String) = (values[k] as? JsonValue.Str)?.value.orEmpty()
        val weight = (values["weight"] as? JsonValue.Num)?.lexical.orEmpty()
        return CustomSeed(text("brand"), text("type"), text("subtype"), "", text("color_hex"), text("diameter"), weight)
    }
}

data class CustomSeed(val brand:String="",val material:String="",val product:String="",val color:String="",val hex:String="#000000",val diameter:String="1.75",val mass:String="1000")

private fun CustomRecord.asCatalogEntry()=CatalogEntry(id,"","",brand,material,product,colorName,colorHex,diameterMm,massG,null,null,null,null,null,null,"user")

fun CatalogEntry.toRecord()=FilamentRecord(packageId,variantId,productId,FieldValue(brand,"OFD $sourceRevision"),FieldValue(material,"OFD $sourceRevision"),FieldValue(product,"OFD $sourceRevision"),FieldValue(colorName,"OFD $sourceRevision"),FieldValue(colorHex,"OFD $sourceRevision"),FieldValue(diameterMm,"OFD $sourceRevision"),FieldValue(massG,"OFD $sourceRevision"),nozzleMinC?.let{FieldValue(it,"OFD $sourceRevision")},nozzleMaxC?.let{FieldValue(it,"OFD $sourceRevision")},bedMinC?.let{FieldValue(it,"OFD $sourceRevision")},bedMaxC?.let{FieldValue(it,"OFD $sourceRevision")},gtin,sku,sourceRevision,Provenance.CATALOG)

package net.jamesjennison.spoolio

import android.content.Context
import android.nfc.*
import android.nfc.tech.Ndef
import android.os.Handler
import android.os.Looper
import android.util.Base64
import androidx.compose.runtime.*
import net.jamesjennison.spoolio.core.*
import java.util.concurrent.Executors

class NfcCoordinator(context:Context) {
    private val machine=WriteStateMachine(); private val io=Executors.newSingleThreadExecutor(); private val main=Handler(Looper.getMainLooper())
    private val journal=WriteJournal(context)
    var state by mutableStateOf(machine.state); private set
    var lastRead by mutableStateOf<DecodeResult?>(null); private set
    init { journal.load()?.let{machine.restoreUnknown(it.uid,it.payload);state=machine.state} }
    fun arm(intent:OpenSpoolIntent)=dispatch{machine.arm(intent)}
    fun approveOverwrite()=dispatch{machine.approveOverwrite()}
    fun cancel()=dispatch{machine.cancel();persistOrClear()}
    fun onTag(tag:Tag){ io.execute { handle(tag) } }
    private fun dispatch(block:()->Unit){io.execute{runCatching(block).onFailure{e->main.post{state=state.copy(detail=e.message?:"Operation rejected")}};publish()}}
    private fun publish(){val next=machine.state;main.post{state=next}}
    private fun persistOrClear(){val s=machine.state;when(s.phase){WritePhase.WRITING,WritePhase.VERIFYING,WritePhase.WRITE_OUTCOME_UNKNOWN->{val uid=s.uid;val payload=s.intent?.payload;if(uid!=null&&payload!=null)journal.save(uid,payload)}WritePhase.VERIFIED->journal.clear();else->Unit}}
    private fun handle(tag:Tag){
        val ndef=Ndef.get(tag) ?: run { if(machine.state.phase!=WritePhase.DRAFT)machine.rejectBeforeWrite("Unsupported or unformatted tag. Automatic formatting is disabled.");main.post{state=if(machine.state.phase==WritePhase.DRAFT)state.copy(detail="Unsupported or unformatted tag. Automatic formatting is disabled.")else machine.state};return }
        try {
            ndef.connect()
            val current=ndef.ndefMessage // active RF read; never cachedNdefMessage
            val records=current?.records?.map{TagRecord(it.tnf.toInt(),it.type.toString(Charsets.US_ASCII),it.payload)}?:emptyList()
            val snapshot=TagSnapshot(tag.id.copyOf(),ndef.isWritable,ndef.maxSize,records)
            if(machine.state.phase==WritePhase.VERIFYING||machine.state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN){
                machine.reconciled(snapshot);persistOrClear();main.post{lastRead=decodeSingleOpenSpool(current)};publish();return
            }
            if(machine.state.phase==WritePhase.DRAFT){main.post{lastRead=decodeSingleOpenSpool(current)};return}
            val intent=machine.state.intent ?: return
            val message=NdefMessage(arrayOf(NdefRecord.createMime(OpenSpoolCodec.MIME,intent.payload)))
            val existingOpenSpool=current?.records?.filter{it.tnf==NdefRecord.TNF_MIME_MEDIA&&it.type.toString(Charsets.US_ASCII)==OpenSpoolCodec.MIME}.orEmpty()
            val unsupported=existingOpenSpool.map{OpenSpoolCodec.decode(it.payload)}.firstOrNull{it !is DecodeResult.Supported}
            if(unsupported!=null){val reason=when(unsupported){is DecodeResult.ReadOnly->unsupported.reason;is DecodeResult.Rejected->unsupported.reason;else->"Unsupported OpenSpool profile"};machine.rejectBeforeWrite("Existing OpenSpool content is read-only: $reason");publish();return}
            machine.inspected(snapshot,message.toByteArray().size);publish()
            if(machine.state.phase!=WritePhase.WRITING)return
            val writeUid=machine.state.uid;val writePayload=machine.state.intent?.payload
            if(writeUid==null||writePayload==null||!journal.save(writeUid,writePayload)){machine.writeFailedBeforeCall("Could not durably journal the write; no write was attempted");publish();return}
            try { ndef.writeNdefMessage(message) } catch(e:Exception){ machine.writeInterrupted("Write did not complete: ${e.javaClass.simpleName}");publish();return }
            machine.writeReturned();persistOrClear();publish()
            // This is an uncached RF read after write. Any loss leaves UNKNOWN.
            val fresh=ndef.ndefMessage
            val freshRecords=fresh?.records?.map{TagRecord(it.tnf.toInt(),it.type.toString(Charsets.US_ASCII),it.payload)}?:emptyList()
            machine.reconciled(TagSnapshot(tag.id.copyOf(),ndef.isWritable,ndef.maxSize,freshRecords));persistOrClear();main.post{lastRead=decodeSingleOpenSpool(fresh)};publish()
        } catch(e:Exception){
            if(machine.state.phase==WritePhase.WRITING||machine.state.phase==WritePhase.VERIFYING)machine.writeInterrupted("Tag connection lost")
            else if(machine.state.phase!=WritePhase.DRAFT)machine.rejectBeforeWrite("NFC read failed: ${e.javaClass.simpleName}") else main.post{state=state.copy(detail="NFC read failed: ${e.javaClass.simpleName}")}
            persistOrClear()
            if(machine.state.phase!=WritePhase.DRAFT)publish()
        } finally { runCatching{ndef.close()} }
    }
    private fun decodeSingleOpenSpool(message:NdefMessage?):DecodeResult {val records=message?.records?:emptyArray();if(records.size!=1)return DecodeResult.Rejected("Expected exactly one OpenSpool NDEF record");val record=records.single();if(record.tnf!=NdefRecord.TNF_MIME_MEDIA||record.type.toString(Charsets.US_ASCII)!=OpenSpoolCodec.MIME)return DecodeResult.Rejected("No OpenSpool MIME record found");return OpenSpoolCodec.decode(record.payload)}
}

private class WriteJournal(context:Context){
    data class Entry(val uid:ByteArray,val payload:ByteArray)
    private val prefs=context.getSharedPreferences("nfc-write-journal",Context.MODE_PRIVATE)
    fun save(uid:ByteArray,payload:ByteArray):Boolean=prefs.edit().putInt("version",1).putString("uid",Base64.encodeToString(uid,Base64.NO_WRAP)).putString("payload",Base64.encodeToString(payload,Base64.NO_WRAP)).commit()
    fun load():Entry?=runCatching{if(prefs.getInt("version",0)!=1)return null;val uid=Base64.decode(prefs.getString("uid",null)?:return null,Base64.DEFAULT);val payload=Base64.decode(prefs.getString("payload",null)?:return null,Base64.DEFAULT);if(uid.isEmpty()||payload.isEmpty())return null;Entry(uid,payload)}.getOrNull()
    fun clear():Boolean=prefs.edit().clear().commit()
}

