@Dao interface UserDao { @Query("SELECT * FROM custom_records ORDER BY updated_at DESC") fun customs():Flow<List<CustomRecord>>; @Insert(onConflict=OnConflictStrategy.REPLACE)suspend fun save(record:CustomRecord); @Query("SELECT * FROM recents ORDER BY used_at DESC LIMIT 30")fun recents():Flow<List<Recent>>; @Insert(onConflict=OnConflictStrategy.REPLACE)suspend fun recent(record:Recent) }
@Database(entities=[CustomRecord::class,Recent::class],version=1,exportSchema=true) abstract class UserDatabase:RoomDatabase(){abstract fun user():UserDao}

class DataStore(private val context:Context) {
    val catalog=Room.databaseBuilder(context,CatalogDatabase::class.java,"catalog-e3888b68.db").build()
    val user=Room.databaseBuilder(context,UserDatabase::class.java,"user.db").build()
    suspend fun ensureCatalog() {
        val manifest=context.assets.open("ofd-catalog-manifest.json").use{StrictJson(4096).parse(it.readBytes()) as? JsonValue.Obj?:error("Catalog manifest is not an object")}
        require(manifest.string("source")=="OpenFilamentCollective/open-filament-database"&&manifest.string("format")=="spoolio-tsv-gzip-v1"){"Unsupported catalog manifest"}
        val expectedCount=manifest.int("packages")?:error("Catalog package count missing")
        val expectedDigest=manifest.string("sha256")?:error("Catalog digest missing")
        if(catalog.catalog().count()==expectedCount)return
        val compressed=context.assets.open("ofd-catalog.tsv.gzip").use{it.readBytes()}
        val actualDigest=MessageDigest.getInstance("SHA-256").digest(compressed).joinToString(""){"%02x".format(it)}
        require(actualDigest==expectedDigest){"Bundled catalog digest mismatch"}
        val entries=ArrayList<CatalogEntry>(expectedCount)
        GZIPInputStream(compressed.inputStream()).bufferedReader().useLines { lines ->
            val iterator=lines.iterator(); require(iterator.hasNext()); val header=iterator.next(); require(header.startsWith("package_id\t"))
            while(iterator.hasNext()){ val f=iterator.next().split('\t'); require(f.size==17);entries += CatalogEntry(f[0],f[1],f[2],f[3],f[4],f[5],f[6],f[7],f[8],f[9].toInt(),f[10].toIntOrNull(),f[11].toIntOrNull(),f[12].toIntOrNull(),f[13].toIntOrNull(),f[14].ifEmpty{null},f[15].ifEmpty{null},f[16]) }
        }
        require(entries.size==expectedCount&&entries.map{it.packageId}.toSet().size==expectedCount){"Catalog count or package identifiers are invalid"}
        catalog.withTransaction { catalog.catalog().clear();entries.chunked(500).forEach{catalog.catalog().insert(it)};check(catalog.catalog().count()==expectedCount){"Catalog transaction did not install the complete generation"} }
    }
}

